    this.library = new StudioLibrary(this);
    this.create = new StudioCreate(this);
    this.clipper = new StudioClipper(this);
    this.talkReel = new StudioTalkReel(this);
    this.footage = new StudioFootage(this);
    this.compiler = new StudioCompiler(this);
    this.longcut = new StudioLongcut(this);
    this.assets = new StudioAssets(this);
    this.outputs = new StudioOutputs(this);
    this.storyboard = new StudioStoryboard(this);
    this.cast = new StudioCast(this);
